// db/schema.sql is the source of truth; the server needs it as a string it can
// run at boot, and bundlers won't follow a runtime file read. Generated file is
// checked in, and tests/schema.test.ts fails if it drifts.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const sql = readFileSync(join(root, "db/schema.sql"), "utf8");

writeFileSync(
  join(root, "src/lib/schema.generated.ts"),
  `// GENERATED by scripts/build-schema.mjs from db/schema.sql — do not edit.\n` +
    `export const SCHEMA_SQL = ${JSON.stringify(sql)};\n`,
);
console.log("wrote src/lib/schema.generated.ts");
